-- PT119-S4-Q1. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT119-S4-Q1$batch03$ AND q.stimulus=$batch03$Considering that Mark Twain is Samuel Clemens, I have always found it amazing that very few people know that Samuel Clemens was a writer, since almost everybody knows that Mark Twain was one.$batch03$ AND q.prompt=$batch03$Which one of the following, if true, would most effectively resolve the apparent paradox above?$batch03$ AND q.correct_choice=$batch03$C$batch03$) THEN RAISE EXCEPTION 'Question changed: PT119-S4-Q1'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT119-S4-Q1$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT119-S4-Q1'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT119-S4-Q1$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$Mark Twain is Samuel Clemens, and almost everyone knows Mark Twain was a writer.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$Very few people know Samuel Clemens was a writer?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$Knowing "Twain was a writer" gives you "Clemens was a writer" only if you also know they are the same person. If most people do not know that, there is nothing strange about the gap.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Find that most people do not know Twain and Clemens are the same person.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT119-S4-Q1$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$Not having read the books would apply under either name, so it cannot explain knowing one fact but not the other.$batch03$), ($batch03$B$batch03$, $batch03$Everyone who knows about Clemens also knowing about Twain is consistent with the gap but does not explain why so few know about Clemens.$batch03$), ($batch03$C$batch03$, $batch03$Most people do not know Twain is Clemens, so they cannot carry "writer" from one name to the other.$batch03$), ($batch03$D$batch03$, $batch03$Holding conflicting beliefs about authors in general does not explain this specific gap.$batch03$), ($batch03$E$batch03$, $batch03$"Some people" knowing the pseudonym fits the puzzle but does not explain why most do not know Clemens was a writer.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT119-S4-Q1$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
